export const meta = {
  name: 'mythosmini-quality-push',
  description: 'Fan-out analysis to design the highest-quality tiny-model training run',
  phases: [
    { title: 'Analyze', detail: 'parallel readers over journal, code, and external research' },
    { title: 'Verify', detail: 'adversarial check of proposals' },
    { title: 'Synthesize', detail: 'ranked implementation plan' },
  ],
}

const FINDINGS = {
  type: 'object',
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'detail', 'expected_gain', 'effort', 'risk'],
        properties: {
          title: { type: 'string' },
          detail: { type: 'string', description: 'concrete, implementable description with file paths and exact changes' },
          expected_gain: { type: 'string', description: 'expected benchmark/throughput impact and why' },
          effort: { type: 'string', enum: ['small', 'medium', 'large'] },
          risk: { type: 'string' },
        },
      },
    },
  },
}

const VERDICT = {
  type: 'object',
  required: ['is_sound', 'reasoning', 'fix_if_flawed'],
  properties: {
    is_sound: { type: 'boolean' },
    reasoning: { type: 'string' },
    fix_if_flawed: { type: 'string' },
  },
}

phase('Analyze')
const CONTEXT = `Repo: /home/lane/MythosMini — a 1,050,241-param byte-level (vocab 257) looped-shared-block transformer trained on fineweb-edu, benchmarked on WikiText-2 byte PPL, BLiMP, ARC-Easy against the Tiny-ML leaderboard (overall = mean of blimp, arc, normalized wiki score; efficiency = overall/log10(params+1) so PARAMETER GROWTH IS PENALIZED only logarithmically — doubling params costs ~5% efficiency but any overall gain counts fully). Current pipeline: procedural Dyck warmup -> 2B-token training (NAdamW, WSD schedule) -> 3-round recursive STM -> benchmark all checkpoints -> SLERP tournament -> SFT instruct phase -> instruct SLERP. Architecture: 4 prelude + 1 shared block looped 2-6x with per-loop LoRA + 4 coda, dim 96, RMSNorm/RoPE/SwiGLU, tied embeddings, DSA-style sparse attention (shared model-level lightning indexer, top-128 keys, 64 local window, FlexAttention short path, chunked long path, 1M max context), FP4 E2M1 QAT on all linears. Recent regression: moving the indexer from per-attention to one shared model-level indexer + detaching the indexer bias for prelude/coda blocks raised throughput 0.85->1.19 Mtok/s but the verification run scored 59.47 overall vs 60.40 before, AND its STM round 3 NaN-diverged (prior runs round 3 gave +0.57; NaN also seen once before with output-embedding centering). All-time best: 60.41 (recursive STM, commit accd37b). GPU: one RTX 5090 32GB, torch 2.10.0+cu128. Known: full-model torch.compile broken (inductor dtype bug + flex recompile issues), STM phase runs at only ~76 ktok/s vs training 1.19 Mtok/s. USER GOAL: push output quality as far as possible toward Gemma-class coherence (text in/text out) — ambition is the point; consider parameter growth, distillation, synthetic data, anything that fits one 5090.`

const results = await parallel([
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/journal.md IN FULL and /home/lane/MythosMini/scores.md. Extract every technique that was tried with its measured outcome. Produce findings: which proven-good techniques are NOT currently in the default pipeline (or were weakened), which failed approaches must not be retried, and what the data says about where the 59.47 vs 60.40 regression came from. Be specific about numbers.`, { label: 'history-miner', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/src/mythosmini/model/transformer.py, src/mythosmini/training/loop.py, src/mythosmini/training/stm.py, src/mythosmini/training/optimizer.py, src/mythosmini/training/scheduler.py, src/mythosmini/config.py. Hunt for QUALITY bugs and theory problems: (1) is the shared model-level indexer (selection computed from embedding output, reused by all 9 blocks incl. prelude/coda with detached bias) theoretically weaker than per-layer indexers, and how to get quality back cheaply? (2) What plausibly causes STM round-3 NaN at constant lr 3e-4 on FP4+sparse weights (look at the detached-bias gradient path, FP4 STE, the indexer gate growth, missing eps/clamps)? Propose concrete fixes with exact code locations. (3) Any other quality-harming detail (init, lr, schedule, loop sampling, tied embedding scale).`, { label: 'code-auditor', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nResearch via web search: state-of-the-art techniques (2024-2026) for maximizing quality of SUB-10M-parameter language models. Focus on: hyperparameter scaling laws for tiny models (muP, depth/width, lr vs size — note current peak_lr 3e-3 for dim 96), modern optimizers (Muon, AdamW variants, schedule-free), data curriculum beyond simple filtering, repeated-epoch vs fresh-data tradeoffs at 2B tokens for 1M params (extreme overtraining — what do papers say), and embedding/softmax tricks for byte-level models. Each finding must be implementable on one RTX 5090 in this codebase.`, { label: 'research-tiny-lm', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nResearch via web search: the single most documented path to coherent tiny models is DATA: TinyStories (arXiv 2305.07759) showed 1-10M models produce fluent coherent text when trained on simple synthetic stories. Research: (1) TinyStories and successors — exact data recipes, model sizes, documented quality; (2) knowledge distillation from open teachers (Qwen3-0.6B, SmolLM2-135M/360M, Gemma-3-270M) into a BYTE-LEVEL student (vocab 257) — vocabulary-mismatch distillation (universal logit distillation, synthetic-text generation instead of logit matching); (3) BabyLM challenge winners 2023-2025 exact recipes at 10-100M words; (4) feasibility: generating 100M-1B tokens of TinyStories-style text with a small teacher on one RTX 5090 via vLLM — tokens/hour estimates; or existing open datasets (TinyStories on HF, SmolTalk, Cosmopedia) we could mix in DIRECTLY without generating. CAVEAT to weigh: our benchmarks are WikiText-2 byte PPL + BLiMP + ARC-Easy — would simple-English synthetic data hurt wiki PPL while helping BLiMP/coherence? Concrete, implementable findings only.`, { label: 'research-data', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/src/mythosmini/training/stm.py and src/mythosmini/benchmarks/*.py and src/mythosmini/merging/tournament.py. The STM phase runs at ~76 ktok/s while main training hits 1.19 Mtok/s — find out why (per-sample loss with reduction=none, fixed loops=4, micro 128 after OOM shrink, flex recompiles from varying batch shapes — note dynamo recompile limit 8 with dynamic=False compile of flex_attention, the final partial batch shape). Propose concrete speedups with exact code changes. Also check benchmark/tournament phases for waste. Target: STM phase at >=500 ktok/s.`, { label: 'stm-speed', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/train.py, src/mythosmini/hardware/autotune.py, src/mythosmini/training/loop.py, src/mythosmini/model/transformer.py. Training currently 1.19 Mtok/s at micro 64 (autotuned; dense model used to autotune to 256 and hit 2.4 Mtok/s). Find remaining throughput AND evaluate scaling up: why does autotune pick 64 (O(n^2) bool selection mask at batch 256 + topk buffers?), can selection be block-sparse at flex BLOCK_SIZE granularity (mask_mod has much cheaper backward than score_mod), bitpacking/bf16 scores, grad-accum tradeoffs. Then: given efficiency only penalizes log10(params), what ModelConfig (dim 128/160/192, heads, ffn, prelude/coda counts) maximizes overall score per wall-clock hour at this throughput? Estimate params and tok/s for 2-3 candidate configs. Propose exact changes.`, { label: 'train-speed-scale', phase: 'Analyze', schema: FINDINGS }),
])

phase('Verify')
const SRC = ['history', 'code', 'tiny-lm', 'data', 'stm-speed', 'train-scale']
const all = results.flatMap((r, i) => ((r && r.findings) || []).map(f => ({ ...f, src: SRC[i] })))
log(`${all.length} raw findings collected`)
const verified = await parallel(all.map(f => () =>
  agent(`${CONTEXT}\n\nAdversarially review this proposal for the MythosMini codebase. Read the actual code it touches before judging. Refute it if: already tried and failed per journal.md, theoretically unsound at ~1M params, won't fit one RTX 5090, conflicts with the leaderboard benchmark setup (byte-level, fixed eval: WikiText-2 byte PPL + BLiMP + ARC-Easy), or the expected gain is wishful. PROPOSAL [from ${f.src}]: ${f.title} — ${f.detail} — expected: ${f.expected_gain} — risk: ${f.risk}`, { label: `verify:${f.title.slice(0, 30)}`, phase: 'Verify', schema: VERDICT })
    .then(v => ({ ...f, verdict: v }))
))
const sound = verified.filter(Boolean).filter(f => f.verdict && f.verdict.is_sound)
log(`${sound.length}/${all.length} findings survived adversarial review`)

phase('Synthesize')
const plan = await agent(`${CONTEXT}\n\nYou are the lead architect. Here are adversarially-verified findings for maximizing MythosMini quality (recover 59.47->60.4+, then push as far beyond as possible toward Gemma-class coherence) plus throughput. Produce a final ordered implementation plan: max 10 changes, ordered by (expected gain / effort), each with exact files, exact change description, and how to verify. Mark each QUALITY vs SPEED vs DATA. Respect the repo rule: one training-behavior feature per 2B verification run — group into at most 3 run-batches. If synthetic/open data mixing survived review, include the exact recipe (dataset or teacher, volume, mixing ratio, expected effect on each of the three benchmarks). FINDINGS:\n${JSON.stringify(sound, null, 1)}`, { label: 'synthesizer', phase: 'Synthesize' })
return { plan, soundCount: sound.length, totalCount: all.length }
